{
  "technical_and_design_decisions": [
    "Baseline platform: Java 17+, Spring Framework 6.x and Spring Boot 3.x, consistent with the stated Spring 6 requirement.",
    "Service discovery: use Spring Cloud Netflix Eureka client; each s-c-s module and the xd-admin server embed a Eureka client that self-registers and periodically updates its status/metadata (U1, U4).",
    "Admin SPI: define a deployment-independent Admin SPI interface (container, stream, module, job operations); controllers depend only on the SPI and a Spring profile/condition-based loader selects the concrete SPI implementation per deployment target (U2).",
    "Metrics capture: after a short spike comparing Spring Integration channel interception versus Spring Boot Actuator, adopt Spring Boot Actuator metrics as the primary capture mechanism because it requires no changes to module internals and is already present in Boot-based modules (U3).",
    "Metrics exposure: expose captured metrics from the admin server via new REST endpoints under the existing admin API (U3).",
    "Metrics persistence: use Spring Boot's metric export API with a Redis writer as the default store and a 5-second default export interval, configurable via properties (U7).",
    "FTP module port: reimplement the XD FTP module as a Spring Cloud Stream source using Spring Integration's FTP inbound channel adapter, packaged with the s-c-s module launcher (U6).",
    "CI: set up automated build/test pipelines for s-c-s repositories (U5) and a separate pipeline that builds, bundles, and pushes the module-launcher Docker image to the existing 'springcloud' DockerHub organization (U8)."
  ],
  "assumptions": [
    "A single developer performs all work; estimates are effort in work-hours, not elapsed calendar time.",
    "The developer is experienced with Spring Framework, Spring Boot, Spring Integration, Spring Cloud Stream, Spring XD codebases, and Docker.",
    "The existing Spring XD and s-c-s source code, build systems (Maven/Gradle), and repositories are available and accessible.",
    "A Eureka server instance is available in development and CI test environments.",
    "CI infrastructure (e.g., Jenkins/Concourse/GitHub Actions runners) and a Docker daemon for image builds are already provisioned.",
    "Credentials and permissions exist to push images to the 'springcloud' DockerHub organization.",
    "A Redis instance is available for metrics persistence testing.",
    "Scope is limited to the capabilities described in U1-U8; no UI work, security hardening beyond defaults, or production deployment is included.",
    "Refactoring controllers (U2) must preserve existing REST API behavior and pass existing controller tests after adaptation."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Overall architecture and technical design",
      "activity_description": "Produce the overall design covering Eureka registration model for modules and admin, the Admin SPI contract, and the metrics capture/persistence architecture; document key decisions and API shapes.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A2",
      "activity_name": "Development environment and dependency setup",
      "activity_description": "Prepare local development environment, add Spring Cloud Eureka, Actuator, and related dependencies to build descriptors, and align module build configurations with Java 17 / Spring 6 baseline.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A3",
      "activity_name": "U1: Implement module state registration with Eureka",
      "activity_description": "Implement Eureka client integration in s-c-s modules so each module registers itself and adds/updates its current state (metadata/status) in Eureka for discovery.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A4",
      "activity_name": "U1: Tests for module registration",
      "activity_description": "Write unit and integration tests verifying module registration, state updates, and deregistration behavior against a test Eureka server.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A5",
      "activity_name": "U2: Design and implement Admin SPI contract",
      "activity_description": "Define the Admin SPI interfaces for container, stream, module, and job operations, plus the selection mechanism that loads the appropriate SPI implementation based on the deployment environment.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A6",
      "activity_name": "U2: Refactor ContainersController to SPI",
      "activity_description": "Refactor ContainersController to delegate to the Admin SPI instead of direct container coupling, preserving existing REST behavior.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A7",
      "activity_name": "U2: Refactor StreamsController to SPI",
      "activity_description": "Refactor StreamsController to delegate stream lifecycle operations to the Admin SPI, preserving existing REST behavior.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A8",
      "activity_name": "U2: Refactor ModulesController to SPI",
      "activity_description": "Refactor ModulesController to delegate module registry operations to the Admin SPI, preserving existing REST behavior.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A9",
      "activity_name": "U2: Refactor JobsController to SPI",
      "activity_description": "Refactor JobsController to delegate job lifecycle operations to the Admin SPI, preserving existing REST behavior.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A10",
      "activity_name": "U2: Adapt and extend controller tests",
      "activity_description": "Adapt existing controller test suites to the SPI-based design with mock SPI implementations, and add tests for SPI implementation selection per deployment.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A11",
      "activity_name": "U3: Spike - evaluate metrics capture options",
      "activity_description": "Technical spike comparing Spring Integration channel() interception and Spring Boot Actuator() APIs for capturing module (cf app) metrics; document findings and confirm approach.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A12",
      "activity_name": "U3: Implement direct module metrics capture",
      "activity_description": "Implement metrics capture from modules (cf apps) directly, decoupled from xd-container, using the approach selected in the spike.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A13",
      "activity_name": "U3: Expose captured metrics via REST API",
      "activity_description": "Implement REST endpoints on the admin server to relay captured module metrics to clients.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A14",
      "activity_name": "U3: Tests for metrics capture and REST API",
      "activity_description": "Write unit and integration tests for metrics capture and the new metrics REST endpoints.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A15",
      "activity_name": "U4: Implement xd-admin self-registration with Eureka",
      "activity_description": "Implement Eureka client self-registration in the xd-admin server so it is exposed as a discoverable endpoint, including configuration of instance metadata.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A16",
      "activity_name": "U4: Tests for admin registration",
      "activity_description": "Write unit and integration tests verifying admin server registration and discoverability via Eureka.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A17",
      "activity_name": "U5: Set up CI builds for s-c-s",
      "activity_description": "Configure CI pipelines that incrementally build and run tests on every code commit for the s-c-s repositories, including build status reporting.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A18",
      "activity_name": "U6: Port FTP module from XD to s-c-s",
      "activity_description": "Port the XD FTP module into the s-c-s repository as a Spring Cloud Stream source module (based on Spring Integration FTP support), adapted to the module-launcher packaging model.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A19",
      "activity_name": "U6: Tests for FTP source module",
      "activity_description": "Write unit and integration tests for the ported FTP source module, including tests against an embedded/test FTP server.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A20",
      "activity_name": "U7: Implement metrics persistence",
      "activity_description": "Implement metrics persistence using Spring Boot's export() API with Redis as the default store and a configurable snapshot interval (default 5s), integrated with the metrics relay.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A21",
      "activity_name": "U7: Tests for metrics persistence",
      "activity_description": "Write unit and integration tests verifying metric snapshot export to Redis at the configured interval.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A22",
      "activity_name": "U8: CI workflow for module-launcher Docker image",
      "activity_description": "Create a CI workflow that builds and bundles the module-launcher Docker image and uploads it to the existing 'springcloud' DockerHub organization, removing the need for a local private registry.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A23",
      "activity_name": "End-to-end integration and system testing",
      "activity_description": "Perform end-to-end integration testing across all stories: module/admin Eureka registration, SPI-based controllers, metrics capture/persistence/REST relay, FTP source in a streaming pipeline, and CI-produced artifacts.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A24",
      "activity_name": "Documentation",
      "activity_description": "Write developer and user documentation: configuration properties, new REST endpoints, SPI contract, FTP module usage, and CI/CD pipeline usage.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A25",
      "activity_name": "Code review, rework, and defect fixing",
      "activity_description": "Address findings from self-review and integration testing, refactor as needed, and fix defects discovered during testing.",
      "most_likely_effort": 16
    }
  ],
  "reported_total": {
    "most_likely_effort": 348
  }
}
